const r=document.querySelectorAll("[data-reveal]");if(r.length&&"IntersectionObserver"in window&&!matchMedia("(prefers-reduced-motion: reduce)").matches){const e=new IntersectionObserver(s=>{for(const t of s)t.isIntersecting&&(t.target.classList.add("is-visible"),e.unobserve(t.target))},{rootMargin:"0px 0px -8% 0px",threshold:.05});r.forEach(s=>e.observe(s))}else r.forEach(e=>e.classList.add("is-visible"));
